    {"id": "ENEM PPL 2025|180", "bank": "ENEM PPL", "exam": "ENEM PPL 2025", "num": 180, "page": 31, "area": "Álgebra de funções", "subject": "Função Afim", "subtopic": "Interseção de duas retas (ponto de equilíbrio)", "competency": "C5", "skill": "H21", "type": "Modelagem", "visual": "Nenhum", "context": "Transporte", "difficulty": "Inteligente", "answer": "C", "summary": "Igualar volumes: t = (VT − 100)/2 → σ1 = 2VT/(VT − 100)", "archetype": "A92", "second": "Expressões Algébricas e Fatoração", "crossArea": true, "changedAnswer": null}
